'use client'

import React, { createContext, useCallback, useContext, useMemo, useState } from 'react'
import styled, { keyframes } from 'styled-components'
import { IoClose, IoCheckmarkCircle, IoAlertCircle, IoInformationCircle } from 'react-icons/io5'

export type ToastType = 'success' | 'error' | 'info'

interface ToastItem {
  id: number
  message: string
  type: ToastType
  duration: number
}

interface ToastContextValue {
  show: (message: string, type?: ToastType, durationMs?: number) => void
  success: (message: string, durationMs?: number) => void
  error: (message: string, durationMs?: number) => void
  info: (message: string, durationMs?: number) => void
}

const ToastContext = createContext<ToastContextValue | null>(null)

const slideDown = keyframes`
  from { transform: translateY(-8px); opacity: 0; }
  to { transform: translateY(0); opacity: 1; }
`

const deplete = keyframes`
  from { width: 100%; }
  to { width: 0%; }
`

const Container = styled.div`
  position: fixed;
  top: 20px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 8px;
  z-index: 9999;
  pointer-events: none;
`

const Card = styled.div<{ $type: ToastType }>`
  background: ${({ $type }) => ($type === 'success' ? '#4263EB' : $type === 'error' ? '#F03E3E' : '#3391FF')};
  color: #FFFFFF;
  border-radius: 8px;
  pointer-events: all;
  animation: ${slideDown} 0.16s ease both;
  overflow: hidden;
  min-width: 280px;
  max-width: min(360px, calc(100vw - 24px));
  padding: 16px 20px;
`

const Row = styled.div`
  display: flex;
  align-items: center;
  gap: 12px;
`

const IconBox = styled.div<{ $type: ToastType }>`
  display: flex;
  align-items: center;
  justify-content: center;
  color: #FFFFFF;
`

const Message = styled.div`
  font-size: 14px;
  line-height: 1.45;
  color: #FFFFFF;
  font-weight: 500;
  flex: 1;
`

const CloseButton = styled.button`
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 24px;
  height: 24px;
  color: #FFFFFF;
  opacity: 0.8;
  transition: opacity 0.2s;

  &:hover {
    opacity: 1;
  }
`



const TYPE_ICON: Record<ToastType, React.ComponentType<{ size?: number }>> = {
  success: IoCheckmarkCircle,
  error: IoAlertCircle,
  info: IoInformationCircle,
}

export function ToastProvider({ children }: { children: React.ReactNode }) {
  const [toasts, setToasts] = useState<ToastItem[]>([])

  const remove = useCallback((id: number) => {
    setToasts((prev) => prev.filter((t) => t.id !== id))
  }, [])

  const show = useCallback((message: string, type: ToastType = 'info', durationMs = 2500) => {
    const id = Date.now() + Math.random()
    setToasts((prev) => [...prev, { id, message, type, duration: durationMs }])
    window.setTimeout(() => remove(id), durationMs)
  }, [remove])

  const ctx = useMemo<ToastContextValue>(() => ({
    show,
    success: (m, d) => show(m, 'success', d),
    error: (m, d) => show(m, 'error', d),
    info: (m, d) => show(m, 'info', d),
  }), [show])

  return (
    <ToastContext.Provider value={ctx}>
      {children}
      <Container>
        {toasts.map((t) => {
          const Icon = TYPE_ICON[t.type]
          return (
            <Card key={t.id} $type={t.type}>
              <Row>
                <IconBox $type={t.type}><Icon size={24} /></IconBox>
                <Message>{t.message}</Message>
                <CloseButton aria-label="close" onClick={() => remove(t.id)}>
                  <IoClose size={20} />
                </CloseButton>
              </Row>
            </Card>
          )
        })}
      </Container>
    </ToastContext.Provider>
  )
}

export function useToast() {
  const ctx = useContext(ToastContext)
  if (!ctx) throw new Error('useToast must be used within ToastProvider')
  return ctx
}
